	return AuthorUpdate{
		...b
		data: b.data.with_cleared('books')
	}
}

// exec updates the rows and their edges, in one transaction, and returns how
// many there were.
pub fn (b AuthorUpdate) exec() !int {
	return b.graph.client.update(b.data)
}

// AuthorDeleteOne builds the delete of one `authors` row. Start one with
// `Graph.authors().delete_one(node)` or `delete_one_id(id)`.
pub struct AuthorDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q AuthorQuery) delete_one(node AuthorNode) AuthorDeleteOne {
	return q.delete_one_id(node.author.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q AuthorQuery) delete_one_id(id int) AuthorDeleteOne {
	return AuthorDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'authors'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b AuthorDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'authors'
		}
	}
}

// AuthorDelete builds the delete of the `authors` rows that match its conditions.
// Start one with `Graph.authors().delete()`.
pub struct AuthorDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q AuthorQuery) delete() AuthorDelete {
	return AuthorDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'authors'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b AuthorDelete) where(conds ...load.Cond) AuthorDelete {
	return AuthorDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

