// authors_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) authors_by_keys(keys []string) ![]AuthorNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.authors().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]AuthorNode{}
	for row in rows {
		by_key[row.author.id.str()] = row
	}
	mut found := []AuthorNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'authors'
			}
		}
	}
	return found
}

// CreateAuthorInput is what a create of a `authors` row sets, as the GraphQL input
// `CreateAuthorInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateAuthorInput {
pub mut:
	name     ?string
	born     ?int
	book_ids []int
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b AuthorCreate) set_input(input CreateAuthorInput) AuthorCreate {
	mut next := b
	if v := input.name {
		next = next.set_name(v)
	}
	if v := input.born {
		next = next.set_born(v)
	}
	if input.book_ids.len > 0 {
		next = next.add_books_ids(...input.book_ids)
	}
	return next
}

// UpdateAuthorInput is what a update of a `authors` row sets, as the GraphQL input
// `UpdateAuthorInput` gives it: `none` and empty lists leave things as
// they are.
pub struct UpdateAuthorInput {
pub mut:
	name            ?string
	born            ?int
	add_book_ids    []int
	remove_book_ids []int
	clear_books     bool
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b AuthorUpdateOne) set_input(input UpdateAuthorInput) AuthorUpdateOne {
	mut next := b
	if input.clear_books {
		next = next.clear_books()
	}
	if v := input.name {
		next = next.set_name(v)
	}
	if v := input.born {
		next = next.set_born(v)
	}
	if input.add_book_ids.len > 0 {
		next = next.add_books_ids(...input.add_book_ids)
	}
	if input.remove_book_ids.len > 0 {
		next = next.remove_books_ids(...input.remove_book_ids)
	}
	return next
}
